  "headline": "Celecoxib is not on FDA's shortage list as of 2026-10-21; Corvale East has 33.5 days on hand and Corvale General has 27.1 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's records show celecoxib is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 441 capsules of the 200 mg presentation at 13.2 per day, providing 33.5 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 524 capsules of the 200 mg presentation at 19.3 per day, providing 27.1 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The rule-based check finds no FDA shortage posting and no action before a posting at a registered plant, so the drug is not considered short by FDA.",
      "cites": ["D3"]
    },
    {
      "text": "The top-ranked option by rule is to buy from Actavis Pharma, Inc., which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Alternative manufacturers include Advanced Rx Pharmacy of Tennessee, LLC and AiPing Pharmaceutical, Inc., also not on FDA's shortage list and with no placeable plant on their labels.",
      "cites": ["D5", "D6"]
    },
    {
      "text": "Advanced Rx of Tennessee, LLC operates a registered repack plant (FEI 3017450153) that received a VAI classification on 2024-09-06.",
      "cites": ["E4", "E3"]
    }
  ]
}
